CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE record_meta(id INTEGER PRIMARY KEY CHECK(id=1), instance_id TEXT NOT NULL, restore_epoch TEXT NOT NULL, schema_version INTEGER NOT NULL);
CREATE TABLE projects(id TEXT PRIMARY KEY, title TEXT NOT NULL, state TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), data TEXT NOT NULL);
CREATE TABLE plans(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), revision INTEGER NOT NULL CHECK(revision>0), state TEXT NOT NULL, data TEXT NOT NULL, UNIQUE(project_id,revision));
CREATE TABLE tasks(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), plan_id TEXT NOT NULL REFERENCES plans(id), assignee TEXT NOT NULL, state TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), generation INTEGER NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 3), data TEXT NOT NULL);
CREATE TABLE dependencies(task_id TEXT NOT NULL REFERENCES tasks(id), parent_id TEXT NOT NULL REFERENCES tasks(id), PRIMARY KEY(task_id,parent_id), CHECK(task_id<>parent_id));
CREATE TABLE role_grants(agent TEXT PRIMARY KEY, model TEXT NOT NULL, family TEXT NOT NULL, role TEXT NOT NULL, state TEXT NOT NULL, revision INTEGER NOT NULL, data TEXT NOT NULL);
CREATE TABLE claims(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), run_id TEXT NOT NULL UNIQUE REFERENCES runs(id) DEFERRABLE INITIALLY DEFERRED, runner TEXT NOT NULL, attempt INTEGER NOT NULL CHECK(attempt BETWEEN 1 AND 3), generation INTEGER NOT NULL, restore_epoch TEXT NOT NULL, lease_until TEXT NOT NULL, state TEXT NOT NULL, data TEXT NOT NULL);
CREATE UNIQUE INDEX one_active_claim_per_task ON claims(task_id) WHERE state='active';
CREATE TABLE runs(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), claim_id TEXT NOT NULL UNIQUE REFERENCES claims(id), attempt INTEGER NOT NULL, request_id TEXT NOT NULL UNIQUE, started_at TEXT NOT NULL, ended_at TEXT, deadline_at TEXT NOT NULL, exit_status INTEGER, closeout TEXT, closeout_validation TEXT NOT NULL, containment_state TEXT NOT NULL, termination_evidence TEXT, usage_state TEXT NOT NULL, usage TEXT, estimated_cost TEXT, actual_charge TEXT, data TEXT NOT NULL, UNIQUE(task_id,attempt));
CREATE TABLE decisions(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), plan_id TEXT NOT NULL REFERENCES plans(id), intended_subject TEXT NOT NULL, expires_at TEXT NOT NULL, state TEXT NOT NULL, revision INTEGER NOT NULL, action TEXT, consumed_at TEXT, data TEXT NOT NULL);
CREATE TABLE notices(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), task_id TEXT REFERENCES tasks(id), sender TEXT NOT NULL, recipient TEXT NOT NULL, kind TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE incidents(id TEXT PRIMARY KEY, task_id TEXT NOT NULL UNIQUE REFERENCES tasks(id), state TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE incident_attempts(incident_id TEXT NOT NULL REFERENCES incidents(id), run_id TEXT NOT NULL REFERENCES runs(id), PRIMARY KEY(incident_id,run_id));
CREATE TABLE scorecard_events(id TEXT PRIMARY KEY, agent TEXT NOT NULL, kind TEXT NOT NULL, source_id TEXT NOT NULL, data TEXT NOT NULL, UNIQUE(source_id,kind));
CREATE TABLE audit_events(seq INTEGER PRIMARY KEY AUTOINCREMENT, actor TEXT NOT NULL, entity_id TEXT NOT NULL, action TEXT NOT NULL, at TEXT NOT NULL, data TEXT NOT NULL);
